"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["41910"],{54025(t){t.exports=JSON.parse('{"id":"F363","slug":"netting-efficiency","name":"Netting Efficiency in Payment Clearing","subject":"Banking & Financial Institutions","section":"Banking","topic":"Payment systems and clearing","level":"Intermediate","aliases":["payment systems and clearing","multilateral netting","bilateral netting","settlement liquidity"],"formula":{"latex":"\\\\text{Net}_{i}=\\\\sum_{j}P_{ji}-\\\\sum_{j}P_{ij},\\\\quad \\\\text{Saving}=1-\\\\frac{\\\\sum_{\\\\text{Net}_{i}>0}\\\\text{Net}_{i}}{\\\\sum P_{ij}}","also":[],"text":"Each bank\'s net position = payments received - payments sent; Multilateral net settlement = sum of the positive net positions; Bilateral netting = for each pair, the difference between the two payments; Liquidity saving = 1 - settled amount / gross payments"},"symbols":[{"symbol":"P_ij","meaning":"Payment due from bank i to bank j","unit":"money"},{"symbol":"Net_i","meaning":"Bank i\'s net position: positive means it is owed money","unit":"money"}],"when_to_use":"Use it to see why clearing houses and central counterparties reduce the cash banks need. Instead of settling every payment separately (gross), obligations are offset, so only net positions move. Multilateral netting through a central party shrinks flows most, but concentrates risk in the center, which is why it requires collateral and a default fund. Enter the payments of three banks row by row.","worked_example":{"problem":"Three banks owe each other (row pays to column): bank 1 pays 100 to bank 2 and 40 to bank 3; bank 2 pays 60 to bank 1 and 90 to bank 3; bank 3 pays 80 to bank 1 and 30 to bank 2.","inputs":{"p":[0,100,40,60,0,90,80,30,0]},"steps":[{"label":"Gross payments","working":null,"value":"400.00"},{"label":"Bilateral netting: sum over pairs of the net payment","working":null,"value":"140.00"},{"label":"Net position of bank 1 = received - paid","working":"([0, 100, 40, 60, 0, 90, 80, 30, 0][3]+[0, 100, 40, 60, 0, 90, 80, 30, 0][6])-([0, 100, 40, 60, 0, 90, 80, 30, 0][1]+[0, 100, 40, 60, 0, 90, 80, 30, 0][2])","value":"0.00"},{"label":"Net position of bank 2","working":"([0, 100, 40, 60, 0, 90, 80, 30, 0][1]+[0, 100, 40, 60, 0, 90, 80, 30, 0][7])-([0, 100, 40, 60, 0, 90, 80, 30, 0][3]+[0, 100, 40, 60, 0, 90, 80, 30, 0][5])","value":"-20.00"},{"label":"Net position of bank 3","working":"([0, 100, 40, 60, 0, 90, 80, 30, 0][2]+[0, 100, 40, 60, 0, 90, 80, 30, 0][5])-([0, 100, 40, 60, 0, 90, 80, 30, 0][6]+[0, 100, 40, 60, 0, 90, 80, 30, 0][7])","value":"20.00"},{"label":"Multilateral settlement = sum of positive positions","working":"max(0,0)+max(-20,0)+max(20,0)","value":"20.00"},{"label":"Liquidity saving = 1 - settled / gross","working":"1-20 / 400","value":"95.0%"}],"answer":"Gross payments total 400.00. Netting each pair separately cuts that to 140.00. Multilateral netting leaves net positions of 0.00, -20.00 and 20.00 for the three banks, so only 20.00 has to move, a liquidity saving of 95.0% compared with gross settlement."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Payments matrix, row by row (diagonal = 0)","unit":"money","type":"list","default":[0,100,40,60,0,90,80,30,0],"hint":"Nine numbers for three banks."}],"checks":[{"expr":"count(p)==9 and p[0]==0 and p[4]==0 and p[8]==0","message":"Enter nine payments for three banks, with zeros on the diagonal."}],"steps":[{"id":"gross","label":"Gross payments","expr":"sum(p)","format":"money"},{"id":"bil","label":"Bilateral netting: sum over pairs of the net payment","expr":"abs(p[1]-p[3])+abs(p[2]-p[6])+abs(p[5]-p[7])","format":"money"},{"id":"n1","label":"Net position of bank 1 = received - paid","expr":"(p[3]+p[6])-(p[1]+p[2])","format":"money"},{"id":"n2","label":"Net position of bank 2","expr":"(p[1]+p[7])-(p[3]+p[5])","format":"money"},{"id":"n3","label":"Net position of bank 3","expr":"(p[2]+p[5])-(p[6]+p[7])","format":"money"},{"id":"ms","label":"Multilateral settlement = sum of positive positions","expr":"max(n1,0)+max(n2,0)+max(n3,0)","format":"money"},{"id":"sv","label":"Liquidity saving = 1 - settled / gross","expr":"1-ms/gross","format":"pct1"}],"results":["gross","bil","ms","sv"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"gross":400,"bil":140,"n1":0,"n2":-20,"n3":20,"ms":20,"sv":0.95}},"finder":{"finds":"How much cash netting saves","needs":"A matrix of payments among three banks"},"related":[{"slug":"ccp-initial-margin","name":"Central Counterparty Initial Margin (Value-at-Risk Method)"},{"slug":"counterparty-exposure-netting","name":"Counterparty Exposure, Netting and Potential Future Exposure"},{"slug":"cross-border-payment-cost","name":"Cross-Border Payment All-In Cost"}],"related_ids":["F349","F385","F364"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mtext>Net</mtext><mi>i</mi></msub><mo>=</mo><munder><mo>\u2211</mo><mi>j</mi></munder><msub><mi>P</mi><mrow><mi>j</mi><mi>i</mi></mrow></msub><mo>\u2212</mo><munder><mo>\u2211</mo><mi>j</mi></munder><msub><mi>P</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Saving</mtext><mo>=</mo><mn>1</mn><mo>\u2212</mo><mfrac><mrow><munder><mo>\u2211</mo><mrow><msub><mtext>Net</mtext><mi>i</mi></msub><mo>&gt;</mo><mn>0</mn></mrow></munder><msub><mtext>Net</mtext><mi>i</mi></msub></mrow><mrow><mo>\u2211</mo><msub><mi>P</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Net}_{i}=\\\\sum_{j}P_{ji}-\\\\sum_{j}P_{ij},\\\\quad \\\\text{Saving}=1-\\\\frac{\\\\sum_{\\\\text{Net}_{i}&gt;0}\\\\text{Net}_{i}}{\\\\sum P_{ij}}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><msub><mtext>Net</mtext><mi>i</mi></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Net}_{i}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><munder><mo>\u2211</mo><mi>j</mi></munder><msub><mi>P</mi><mrow><mi>j</mi><mi>i</mi></mrow></msub><mo>\u2212</mo><munder><mo>\u2211</mo><mi>j</mi></munder><msub><mi>P</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\sum_{j}P_{ji}-\\\\sum_{j}P_{ij}</annotation></semantics></math></span>"},{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Saving</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Saving}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mn>1</mn><mo>\u2212</mo><mfrac><mrow><munder><mo>\u2211</mo><mrow><msub><mtext>Net</mtext><mi>i</mi></msub><mo>&gt;</mo><mn>0</mn></mrow></munder><msub><mtext>Net</mtext><mi>i</mi></msub></mrow><mrow><mo>\u2211</mo><msub><mi>P</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub></mrow></mfrac></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =1-\\\\frac{\\\\sum_{\\\\text{Net}_{i}&gt;0}\\\\text{Net}_{i}}{\\\\sum P_{ij}}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"net-worth","name":"Net Worth and Balance Sheet Ratios"},"next":{"slug":"newton-implied-vol","name":"Newton\'s Method for Implied Volatility"},"lesson":null,"total":522}')}}]);